// Generated by LCD Wizard - the Canvas widget's pixels.
//
// Each canvas is given a buffer when its screen is built, the size of the
// widget, and it is freed when the canvas is deleted. The design has PSRAM
// switched on, so the buffer is taken from there, and from internal RAM only
// when there is no PSRAM to be had.

#include "lw_canvas.h"
#include <stdlib.h>
#include <string.h>
#if defined(ESP_PLATFORM)
#include <esp_heap_caps.h>
#endif

#define LW_CANVAS_PSRAM 1

static void * canvas_alloc(size_t bytes)
{
#if defined(ESP_PLATFORM)
#if LW_CANVAS_PSRAM
    void * p = heap_caps_malloc(bytes, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
    if (p) return p;
#endif
    return heap_caps_malloc(bytes, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
#else
    return malloc(bytes);
#endif
}

static void canvas_free(void * p)
{
#if defined(ESP_PLATFORM)
    heap_caps_free(p);
#else
    free(p);
#endif
}

static void canvas_gone(lv_event_t * e)
{
    void * raw = lv_event_get_user_data(e);
    (void)lv_event_get_current_target_obj(e);
    if (raw) canvas_free(raw);
}

bool ui_canvas_attach(lv_obj_t * canvas, int32_t w, int32_t h, lv_color_format_t cf, lv_color_t fill, lv_opa_t opa)
{
    if (!canvas || w < 1 || h < 1) return false;
    const uint32_t stride = lv_draw_buf_width_to_stride((uint32_t)w, cf);
    const size_t bytes = (size_t)stride * (size_t)h + LV_DRAW_BUF_ALIGN;
    void * raw = canvas_alloc(bytes);
    if (!raw) {
        LV_LOG_WARN("Canvas: no memory for its %u bytes of pixels", (unsigned)bytes);
        return false;
    }
    memset(raw, 0, bytes);
    lv_canvas_set_buffer(canvas, lv_draw_buf_align(raw, cf), w, h, cf);
    lv_obj_add_event_cb(canvas, canvas_gone, LV_EVENT_DELETE, raw);
    lv_canvas_fill_bg(canvas, fill, opa);
    return true;
}

void ui_canvas_clear(lv_obj_t * canvas, lv_color_t color, lv_opa_t opa)
{
    // A canvas on a screen that has not been built yet, or has been deleted.
    if (!canvas || !lv_obj_is_valid(canvas)) return;
    if (!(lv_canvas_get_draw_buf(canvas) != NULL)) return;
    lv_canvas_fill_bg(canvas, color, opa);
}

void * ui_canvas_buffer(lv_obj_t * canvas)
{
    if (!canvas) return NULL;
    lv_draw_buf_t * db = lv_canvas_get_draw_buf(canvas);
    return db ? db->data : NULL;
}
